/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Types: Props
 *   Functions: notStarted, answered, decided, idle, Harness, mount, updateCount, luna
 * Tests
 *   - before any run the steps read not run, nothing to answer and no changes
 *   - a possible release that needs Disc and Track Numbers leads the first two steps, with no ready line, and the update waits for the numbers
 *   - while a release is offered for a choice, the update waits for it: the third step offers no button, even with saved changes listed
 *   - the second step counts the lookup answers as the summary does and the records to choose beside them, linking to the first open answer
 *   - once everything is answered the ready line shows and Review changes to apply carries the Update step's count as the primary button, opening that step
 *   - the button waits while the draft has unsaved edits and is not shown on the Update step
 *   - only the records left to choose: the second step names them alone and links to the identity rows
 *   - while the lookup read is pending, and when it fails, the steps show no state rather than a false one
 *   - a running Luna AI analysis, or the free retry left to check an iTunes release, keeps the ready line away and the button plain
 *   - the last answer moves a focus it left on the page to the step to the changes, now the primary button
 *   - a page opened with nothing left to answer leaves the focus where it is
 *   - an applied completion says when the Album was updated in the interface language and opens what was updated; Luna AI's status shows only once Luna ran
 *   - the Luna AI controls are never primary, stop a running analysis, and say when the limit is reached or the provider failed
 *   - a failed Luna AI run is one quiet line that can be ignored while the lookup leads, saying only an unknown outcome that keeps it from starting
 *   - a superseded lookup promises no free retry, and another ended run promises it only while the review's source is current
 * @end-catalog */

import { useState } from 'react';
import { act, cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { MemoryRouter } from 'react-router';
import { captureAccountOperation } from '../../api/accountEpoch';
import { adminWorkspace } from './adminWorkspace';
import type { CatalogReview } from './catalogReviewApi';
import type { ApplyChoice } from './catalogReviewApplyModel';
import { CatalogReviewApply } from './CatalogReviewApply';
import { capturedCatalogReview, catalogReview, reviewJson, session, viewer } from './catalogReviewFixtures.testSupport';
import { pairedLookupResponse, pairingLookupResponse, pairingReview, reviewAfterLookup, reviewIdentityResponse, reviewItunesLookupResponse, reviewLookupResponse } from './catalogReviewLookupFixtures.testSupport';
import type { ReviewIdentityResponse, ReviewLookupResponse } from './catalogReviewLookupApi';
import { CatalogReviewLuna, CatalogReviewSteps } from './CatalogReviewSteps';
import styles from './adminStyles';

/**
 * The three steps above an Album completion's lookup summary, on their own: each step's state from the summary's read and the
 * Update step's count, the ready line and its primary button, an applied completion, the Luna AI line and the Luna AI controls.
 * Reads are answered per path; every name and identifier is synthetic.
 */
const notStarted = (): ReviewLookupResponse => ({ lookup: null, revision: 1, valueRevision: 0, summary: { waiting: { lookup: false, analysis: false }, needsAnswer: { tie: false, conflicts: [] }, lookupAvailable: true } });
/** The applied release's conflicts all answered (the saved values kept). */
function answered(response = reviewLookupResponse()): ReviewLookupResponse {
  const lookup = response.lookup!;
  lookup.needsAnswer = { tie: false, conflicts: [] }; lookup.applied!.conflicts = lookup.applied!.conflicts.map(conflict => ({ ...conflict, answer: 'mine' }));
  response.summary.needsAnswer = { tie: false, conflicts: [] };
  return response;
}
/** The identity read with every row decided. */
const decided = (): ReviewIdentityResponse => { const value = reviewIdentityResponse(); value.identities = value.identities.map(row => ({ ...row, needsAnswer: false })); return value; };
const idle = (item: CatalogReview): CatalogReview => ({ ...item, analysis: { ...item.analysis, state: 'idle', generation: 0, operationId: null, completedChunks: 0, totalChunks: 0, attemptsUsed: 0 }, suggestions: [] });

type Props = { stage?: 'draft' | 'review' | 'apply'; dirty?: boolean; apply?: boolean };
/** The steps and, with `apply`, the Update step beside them, keeping the explicit choices as the review page does. */
function Harness({ item, props, onNavigate }: { item: CatalogReview; props: Props; onNavigate: (stage: 'draft' | 'apply') => void }) {
  const [choices, setChoices] = useState<Record<string, ApplyChoice>>({});
  return <><CatalogReviewSteps item={item} choices={choices} stage={props.stage ?? 'draft'} dirty={props.dirty ?? false} onNavigate={onNavigate} />
    {props.apply && <CatalogReviewApply item={item} choices={choices} disabled={false} onChoose={(key, choice) => setChoices(previous => ({ ...previous, [key]: choice }))}
      onConfirm={() => undefined} />}</>;
}
/** Renders the harness; `lookup` (a body, or a response that may wait) and `identity` answer the reads. */
function mount(item: CatalogReview, lookup: () => ReviewLookupResponse | Promise<Response> = notStarted, identity: () => ReviewIdentityResponse = reviewIdentityResponse, props: Props = {}) {
  const fetch = vi.fn(async (path: string) => {
    if (!path.endsWith('/lookup')) return path.endsWith('/candidates') ? reviewJson(identity()) : reviewJson({ code: 'unexpected' }, 500);
    const value = lookup();
    return value instanceof Promise ? value : reviewJson(value);
  });
  vi.stubGlobal('fetch', fetch);
  const client = new QueryClient({ defaultOptions: { queries: { retry: false } } }); client.setQueryData(['browser-session'], session);
  const onNavigate = vi.fn();
  render(<QueryClientProvider client={client}><MemoryRouter><Harness item={item} props={props} onNavigate={onNavigate} /></MemoryRouter></QueryClientProvider>);
  const steps = () => within(screen.getByRole('group', { name: 'Completion steps' }));
  /** The state shown for the step labelled `label`. */
  const step = (label: string) => steps().getByText(label).nextElementSibling as HTMLElement;
  return { fetch, client, onNavigate, steps, step };
}
beforeEach(() => {
  adminWorkspace.reset(); adminWorkspace.authorize(captureAccountOperation(viewer), true, true, undefined, { editing: true, visibility: true }); adminWorkspace.select('admin');
});
afterEach(() => { cleanup(); adminWorkspace.reset(); vi.unstubAllGlobals(); vi.restoreAllMocks(); });

test('before any run the steps read not run, nothing to answer and no changes', async () => {
  const { step, fetch } = mount(idle(catalogReview()));
  await waitFor(() => expect(step('③ Update original Album')).toHaveTextContent('No changes yet'));
  expect(step('① Find release')).toHaveTextContent('Lookup has not run');
  expect(step('② Answer questions')).toHaveTextContent('Nothing left to answer');
  // A review never captured for lookup has no lookup to read, and Luna AI never ran: no Luna AI line.
  expect(fetch).not.toHaveBeenCalled();
  expect(screen.queryByText(/Luna AI/)).not.toBeInTheDocument();
  expect(screen.queryByRole('button')).not.toBeInTheDocument();
});

test('a possible release that needs Disc and Track Numbers leads the first two steps, with no ready line, and the update waits for the numbers', async () => {
  const { step } = mount(idle(pairingReview()), pairingLookupResponse);
  await waitFor(() => expect(step('① Find release')).toHaveTextContent('Found 1 possible release'));
  expect(step('② Answer questions')).toHaveTextContent('Disc and Track Numbers needed');
  expect(within(step('① Find release')).getByRole('link')).toHaveAttribute('href', '#catalog-review-lookup');
  expect(step('③ Update original Album')).toHaveTextContent('Update after entering Disc and Track Numbers');
  expect(screen.queryByText('Everything is answered; you can update the original Album.')).not.toBeInTheDocument();
});

test('while a release is offered for a choice, the update waits for it: the third step offers no button, even with saved changes listed', async () => {
  // Saved Disc and Track Numbers, which the Update step lists unselected, as after saving numbers that made the release match.
  const base = idle(pairingReview()), item = { ...base, draft: { ...base.draft, tracks: base.draft.tracks.map((track, index) => ({ ...track, discNumber: 1, trackNumber: index + 1 })) } };
  const { step } = mount(item, () => pairedLookupResponse(), reviewIdentityResponse, { apply: true });
  await waitFor(() => expect(step('② Answer questions')).toHaveTextContent('Choose a release'));
  expect(step('① Find release')).toHaveTextContent('Matching release found');
  // The Update step itself lists the saved numbers, but the steps show one next step only.
  await screen.findByRole('button', { name: /^Update original Album/ });
  expect(step('③ Update original Album')).toHaveTextContent('Update after choosing a release');
  expect(screen.queryByRole('button', { name: /^Review changes to apply/ })).not.toBeInTheDocument();
});

test('the second step counts the lookup answers as the summary does and the records to choose beside them, linking to the first open answer', async () => {
  const { step } = mount(reviewAfterLookup(capturedCatalogReview()), () => reviewLookupResponse());
  // Three open conflicts, as the summary counts them, and the guest's record to choose.
  await waitFor(() => expect(step('② Answer questions')).toHaveTextContent('3 answers needed · 1 Artist or label to choose'));
  expect(step('① Find release')).toHaveTextContent('Applied "Synthetic catalog Album (Complete)"');
  expect(within(step('① Find release')).getByRole('link')).toHaveAttribute('href', '#catalog-review-lookup');
  expect(within(step('② Answer questions')).getByRole('link')).toHaveAttribute('href', '#catalog-review-answers');
  const review = await screen.findByRole('button', { name: /^Review changes to apply/ });
  expect(review).not.toHaveClass(styles.primary);
  expect(screen.queryByText('Everything is answered; you can update the original Album.')).not.toBeInTheDocument();
});

/** The Update step's own count, once its reads arrived. */
async function updateCount(above = 0) {
  let count = 0;
  await waitFor(() => { count = Number(/\((\d+)\)/.exec(screen.getByRole('button', { name: /^Update original Album \(\d+\)$/ }).textContent!)![1]); expect(count).toBeGreaterThan(above); });
  return count;
}

test('once everything is answered the ready line shows and Review changes to apply carries the Update step\'s count as the primary button, opening that step', async () => {
  const { step, onNavigate } = mount(reviewAfterLookup(capturedCatalogReview()), answered, decided, { apply: true });
  const count = await updateCount();
  const review = await screen.findByRole('button', { name: `Review changes to apply (${count})` });
  expect(review).toHaveClass(styles.primary);
  expect(step('② Answer questions')).toHaveTextContent('Nothing left to answer');
  expect(step('③ Update original Album')).toHaveTextContent(`${count} change${count === 1 ? '' : 's'} selected`);
  expect(screen.getByText('Everything is answered; you can update the original Album.')).toHaveAttribute('role', 'status');
  // A deselected change counts in both the same way.
  fireEvent.click((await screen.findAllByRole('checkbox')).find(box => (box as HTMLInputElement).checked && !(box as HTMLInputElement).disabled)!);
  expect(await screen.findByRole('button', { name: `Update original Album (${count - 1})` })).toBeVisible();
  expect(await screen.findByRole('button', { name: `Review changes to apply (${count - 1})` })).toHaveClass(styles.primary);
  fireEvent.click(screen.getByRole('button', { name: `Review changes to apply (${count - 1})` }));
  expect(onNavigate).toHaveBeenCalledWith('apply');
});

test('the button waits while the draft has unsaved edits and is not shown on the Update step', async () => {
  const item = reviewAfterLookup(capturedCatalogReview());
  mount(item, answered, decided, { dirty: true });
  expect(await screen.findByRole('button', { name: /^Review changes to apply/ })).toBeDisabled();
  cleanup();
  const { step } = mount(item, answered, decided, { stage: 'apply' });
  await waitFor(() => expect(step('③ Update original Album')).toHaveTextContent(/selected/));
  expect(screen.queryByRole('button', { name: /^Review changes to apply/ })).not.toBeInTheDocument();
  expect(screen.queryByText('Everything is answered; you can update the original Album.')).not.toBeInTheDocument();
});

test('only the records left to choose: the second step names them alone and links to the identity rows', async () => {
  const { step } = mount(reviewAfterLookup(capturedCatalogReview()), answered);
  await waitFor(() => expect(step('② Answer questions')).toHaveTextContent(/^1 Artist or label to choose$/));
  expect(within(step('② Answer questions')).getByRole('link')).toHaveAttribute('href', '#catalog-review-identities');
  expect(screen.queryByText('Everything is answered; you can update the original Album.')).not.toBeInTheDocument();
});

test('while the lookup read is pending, and when it fails, the steps show no state rather than a false one', async () => {
  const read: { answer?: (response: Response) => void } = {};
  const { step, client } = mount(reviewAfterLookup(capturedCatalogReview()), () => new Promise<Response>(resolve => { read.answer = resolve; }), decided);
  await waitFor(() => expect(read.answer).toBeDefined());
  await act(async () => { await new Promise(resolve => setTimeout(resolve, 50)); });
  for (const label of ['① Find release', '② Answer questions', '③ Update original Album']) expect(step(label)).toHaveTextContent(/^—$/);
  await act(async () => { read.answer!(reviewJson({ code: 'unexpected' }, 500)); });
  await waitFor(() => expect(client.getQueryCache().getAll().some(query => query.state.status === 'error')).toBe(true));
  expect(step('① Find release')).toHaveTextContent(/^—$/);
  expect(screen.queryByText('Lookup has not run')).not.toBeInTheDocument();
});

test('a running Luna AI analysis, or the free retry left to check an iTunes release, keeps the ready line away and the button plain', async () => {
  const running = reviewAfterLookup(capturedCatalogReview()); running.analysis = { ...running.analysis, state: 'running' };
  const waiting = () => { const response = answered(); response.summary.waiting = { lookup: false, analysis: true }; return response; };
  let rendered = mount(running, waiting, decided);
  await waitFor(() => expect(rendered.step('③ Update original Album')).toHaveTextContent(/selected/));
  expect(rendered.step('② Answer questions')).toHaveTextContent('Nothing left to answer');
  expect(await screen.findByRole('button', { name: /^Review changes to apply/ })).not.toHaveClass(styles.primary);
  expect(screen.queryByText('Everything is answered; you can update the original Album.')).not.toBeInTheDocument();
  cleanup();
  // An iTunes-only release not checked against MusicBrainz: the summary's free retry is the next step and its only primary button.
  rendered = mount(reviewAfterLookup(capturedCatalogReview()), () => answered(reviewItunesLookupResponse()), decided);
  await waitFor(() => expect(rendered.step('① Find release')).toHaveTextContent('iTunes release applied; retry the lookup for free to check it against MusicBrainz'));
  await waitFor(() => expect(rendered.step('③ Update original Album')).toHaveTextContent(/selected/));
  expect(await screen.findByRole('button', { name: /^Review changes to apply/ })).not.toHaveClass(styles.primary);
  expect(screen.queryByText('Everything is answered; you can update the original Album.')).not.toBeInTheDocument();
});

test('the last answer moves a focus it left on the page to the step to the changes, now the primary button', async () => {
  let open = true;
  const { step, client } = mount(reviewAfterLookup(capturedCatalogReview()), () => open ? reviewLookupResponse() : answered(), decided);
  await waitFor(() => expect(step('② Answer questions')).toHaveTextContent('3 answers needed'));
  expect(document.activeElement).toBe(document.body);
  open = false;
  await act(async () => { await client.invalidateQueries(); });
  const review = await screen.findByRole('button', { name: /^Review changes to apply \(\d+\)$/ });
  await waitFor(() => expect(review).toHaveFocus());
  expect(review).toHaveClass(styles.primary);
});

test('a page opened with nothing left to answer leaves the focus where it is', async () => {
  mount(reviewAfterLookup(capturedCatalogReview()), answered, decided);
  expect(await screen.findByText('Everything is answered; you can update the original Album.')).toBeVisible();
  expect(document.activeElement).toBe(document.body);
});

test('an applied completion says when the Album was updated in the interface language and opens what was updated; Luna AI\'s status shows only once Luna ran', async () => {
  const at = '2026-10-22T01:30:00.000Z';
  const applied = (item: CatalogReview): CatalogReview => ({ ...item, state: 'applied', sourceStatus: 'changed', capabilities: { analysis: false, apply: false },
    applied: { operationId: '30000000-0000-4000-8000-000000000009', at, fields: [{ scope: 'album', slotId: null, field: 'title' }] } });
  const { step, onNavigate } = mount(applied(idle(catalogReview())));
  expect(step('③ Update original Album')).toHaveTextContent(`Updated ${new Date(at).toLocaleString('en-US', { dateStyle: 'medium', timeStyle: 'short' })}`);
  expect(step('① Find release')).toHaveTextContent('—');
  expect(step('② Answer questions')).toHaveTextContent('—');
  expect(screen.queryByRole('link')).not.toBeInTheDocument();
  expect(screen.queryByText(/Luna AI/)).not.toBeInTheDocument();
  fireEvent.click(screen.getByRole('button', { name: 'What was updated' }));
  expect(onNavigate).toHaveBeenCalledWith('apply');
  cleanup();
  mount(applied(catalogReview()));
  expect(screen.getByText('Luna AI (paid, optional)').nextElementSibling).toHaveTextContent('Closed');
});

/** The Luna AI controls on their own, beside a review whose lookup reads `lookup`. */
function luna(item: CatalogReview, lookup: () => ReviewLookupResponse = notStarted) {
  vi.stubGlobal('fetch', vi.fn(async (path: string) => path.endsWith('/lookup') ? reviewJson(lookup()) : reviewJson({ code: 'unexpected' }, 500)));
  const client = new QueryClient({ defaultOptions: { queries: { retry: false } } }); client.setQueryData(['browser-session'], session);
  const element = (value: CatalogReview) => <QueryClientProvider client={client}><CatalogReviewLuna item={value} active={false} canAnalyze={false} onAnalyze={() => undefined}
    onStop={() => undefined} busy={false} /></QueryClientProvider>;
  return { ...render(element(item)), element };
}

test('the Luna AI controls are never primary, stop a running analysis, and say when the limit is reached or the provider failed', () => {
  const onAnalyze = vi.fn(), onStop = vi.fn(), item = catalogReview();
  const client = new QueryClient(); client.setQueryData(['browser-session'], session);
  const view = render(<CatalogReviewLuna item={item} active={false} canAnalyze onAnalyze={onAnalyze} onStop={onStop} busy={false} />,
    { wrapper: ({ children }) => <QueryClientProvider client={client}>{children}</QueryClientProvider> });
  const again = screen.getByRole('button', { name: 'Use Luna AI again (paid)' });
  expect(again).not.toHaveClass(styles.primary);
  fireEvent.click(again); expect(onAnalyze).toHaveBeenCalledTimes(1);
  view.rerender(<CatalogReviewLuna item={{ ...item, analysis: { ...item.analysis, state: 'running' } }} active canAnalyze={false} onAnalyze={onAnalyze} onStop={onStop} busy={false} />);
  const stop = screen.getByRole('button', { name: 'Stop Luna AI' });
  expect(stop).not.toHaveClass(styles.primary);
  fireEvent.click(stop); expect(onStop).toHaveBeenCalledTimes(1);
  expect(screen.getByRole('status')).toHaveTextContent(/Luna AI/);
  view.rerender(<CatalogReviewLuna item={{ ...item, analysis: { ...item.analysis, state: 'needsAttention', generation: 2, issue: 'providerInvalidResponse' } }} active={false} canAnalyze={false}
    onAnalyze={onAnalyze} onStop={onStop} busy={false} />);
  expect(screen.getByRole('button', { name: 'Use Luna AI again (paid)' })).toBeDisabled();
  expect(screen.getByText(/limit/i)).toBeVisible();
  expect(screen.getByRole('status')).toHaveTextContent(/\S/);
  // Without a lookup that leads, a failed run reads calmly beside its reason, never as needing attention.
  expect(screen.getByText('Last run did not succeed')).toBeVisible();
  expect(screen.queryByText(/needs attention/i)).not.toBeInTheDocument();
});

test('a failed Luna AI run is one quiet line that can be ignored while the lookup leads, saying only an unknown outcome that keeps it from starting', async () => {
  const failed = (item: CatalogReview, issue: CatalogReview['analysis']['issue']) => ({ ...item, analysis: { ...item.analysis, state: 'needsAttention' as const, generation: 1, issue } });
  const quiet = 'Luna AI (paid, optional): the last run did not succeed; you can ignore it.';
  // The lookup found a possible release that needs numbers: the failed run is one quiet line, its reason left out.
  const { rerender, element } = luna(failed(pairingReview(), 'providerInvalidResponse'), pairingLookupResponse);
  expect(await screen.findByText(quiet)).toBeVisible();
  expect(screen.queryByText(/could not be validated/)).not.toBeInTheDocument();
  expect(screen.queryByRole('status')).not.toBeInTheDocument();
  expect(screen.getByRole('button', { name: 'Use Luna AI again (paid)' })).not.toHaveClass(styles.primary);
  // An unknown outcome keeps Luna AI from starting, so it is said, muted.
  rerender(element(failed(pairingReview(), 'providerOutcomeUnknown')));
  expect(screen.getByText(quiet)).toBeVisible();
  expect(screen.getByRole('status')).toHaveClass(styles.muted);
  cleanup();
  // A lookup that found nothing to use leaves the run's reason in view.
  luna(failed(pairingReview(), 'providerInvalidResponse'), () => { const response = pairingLookupResponse(); Object.assign(response.lookup!, { candidates: [], outcome: 'noRelease' }); return response; });
  expect(await screen.findByRole('status')).toHaveTextContent(/\S/);
  expect(screen.getByText('Last run did not succeed')).toBeVisible();
  expect(screen.queryByText(quiet)).not.toBeInTheDocument();
});

test('a superseded lookup promises no free retry, and another ended run promises it only while the review\'s source is current', async () => {
  const ended = (state: 'superseded' | 'stopped', issue: 'projectClosed' | 'grantExpired') => () => {
    const response = pairingLookupResponse(); Object.assign(response.lookup!, { state, issue, candidates: [] }); return response; };
  for (const [sourceStatus, stopped] of [['current', 'Lookup did not finish; retry for free'], ['changed', 'Lookup unavailable'], ['unavailable', 'Lookup unavailable']] as const) {
    for (const [response, text] of [[ended('superseded', 'projectClosed'), 'Lookup unavailable'], [ended('stopped', 'grantExpired'), stopped]] as const) {
      const { step } = mount(idle({ ...pairingReview(), sourceStatus }), response);
      await waitFor(() => expect(step('① Find release')).toHaveTextContent(text));
      cleanup();
    }
  }
});
